import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CkKL3Me7.js";const h=JSON.parse('{"title":"Time off","description":"","frontmatter":{},"headers":[],"relativePath":"guide/time-off.md","filePath":"guide/time-off.md"}'),i={name:"guide/time-off.md"};function n(s,e,u,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="time-off" tabindex="-1">Time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time off&quot;">​</a></h1><p>Time off — holidays, sick days, and leave — goes through VERA rather than being logged directly. This keeps your manager in the loop and ensures your capacity is reflected accurately.</p><hr><h2 id="requesting-time-off-pto-holiday" tabindex="-1">Requesting time off (PTO / holiday) <a class="header-anchor" href="#requesting-time-off-pto-holiday" aria-label="Permalink to &quot;Requesting time off (PTO / holiday)&quot;">​</a></h2><p>Tell VERA you need time off and they&#39;ll create a request and notify your manager:</p><blockquote><p>&quot;I need Friday off&quot;</p></blockquote><blockquote><p>&quot;Can I take next Monday and Tuesday as holiday?&quot;</p></blockquote><blockquote><p>&quot;I&#39;d like to request 3 days off from the 14th to the 16th&quot;</p></blockquote><p>Your manager receives a notification and can approve or decline. You&#39;ll be told the outcome.</p><p><strong>Important:</strong> Don&#39;t log time directly to an &quot;out of office&quot; or &quot;holiday&quot; project — requests must go through the approval process so your manager is aware.</p><hr><h2 id="sick-days" tabindex="-1">Sick days <a class="header-anchor" href="#sick-days" aria-label="Permalink to &quot;Sick days&quot;">​</a></h2><p>If you&#39;re unwell, let your manager know directly — they&#39;ll record it for you. You don&#39;t need to create a formal request for a sick day.</p><p>Managers can log a sick day on your behalf:</p><blockquote><p>&quot;Log a sick day for Sarah today&quot;</p></blockquote><blockquote><p>&quot;Mark James as sick for yesterday and today&quot;</p></blockquote><hr><h2 id="leave" tabindex="-1">Leave <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;Leave&quot;">​</a></h2><p>Extended leave (parental, compassionate, unpaid, and so on) works the same way as PTO — request it through VERA and your manager approves.</p><blockquote><p>&quot;I need to request parental leave from the 1st of May&quot;</p></blockquote><hr><h2 id="viewing-your-requests" tabindex="-1">Viewing your requests <a class="header-anchor" href="#viewing-your-requests" aria-label="Permalink to &quot;Viewing your requests&quot;">​</a></h2><blockquote><p>&quot;Show me my time off requests&quot;</p></blockquote><blockquote><p>&quot;Have I got any approved holiday coming up?&quot;</p></blockquote><p>VERA returns a list of your requests and their current status (pending, approved, or declined).</p><hr><h2 id="for-managers-approving-requests" tabindex="-1">For managers: approving requests <a class="header-anchor" href="#for-managers-approving-requests" aria-label="Permalink to &quot;For managers: approving requests&quot;">​</a></h2><p>When a team member requests time off, you&#39;ll receive a Slack message. To approve:</p><blockquote><p>&quot;Approve Sarah&#39;s time off request&quot;</p></blockquote><blockquote><p>&quot;Approve request #42&quot;</p></blockquote><p>To decline:</p><blockquote><p>&quot;Decline Sarah&#39;s request — we need her on the Nike project that week&quot;</p></blockquote><p>VERA notifies the team member of the outcome and, on approval, records the time off against their schedule.</p><hr><h2 id="viewing-pending-requests-managers-and-owners" tabindex="-1">Viewing pending requests (managers and owners) <a class="header-anchor" href="#viewing-pending-requests-managers-and-owners" aria-label="Permalink to &quot;Viewing pending requests (managers and owners)&quot;">​</a></h2><blockquote><p>&quot;Show me all pending time off requests&quot;</p></blockquote><blockquote><p>&quot;Who has holiday approved for next month?&quot;</p></blockquote><hr><h2 id="company-holidays" tabindex="-1">Company holidays <a class="header-anchor" href="#company-holidays" aria-label="Permalink to &quot;Company holidays&quot;">​</a></h2><p>Your organisation&#39;s public holidays are set up by an owner. These are automatically factored into capacity calculations — you don&#39;t need to request them individually.</p><blockquote><p>&quot;What company holidays do we have this year?&quot;</p></blockquote>',41)])])}const q=o(i,[["render",n]]);export{h as __pageData,q as default};
